# Rhode Island General Laws from webserver.rilegislature.gov/Statutes: title index -> chapter (and article) INDEX pages -> each section page; the law is everything after the section's <h3> cite.
import re
BASE = "https://webserver.rilegislature.gov/Statutes/"

def _links(html):
    return re.findall(r'(?i)href="([^"#]+\.htm)"', html)

def _section(url):
    _, html = fetch(url)
    i = html.find("</h3>")
    if i < 0:
        return None
    body = html[i + 5:].replace("\r", " ").replace("\n", " ")      # the source hard-wraps its lines; HTML whitespace is one space
    lines = block_text('<div id="law">' + body + "</div>", id="law").split("\n")
    m = re.match(r"§+\s*([0-9][0-9A-Za-z.\-]*?)\.?\s+(.*)", lines[0]) if lines else None
    if not m:
        log(f"no section mark {url}"); return None
    return {"id": m.group(1), "heading": m.group(2).strip(), "text": "\n".join(lines[1:]).strip(), "url": url}

def _walk(url, seen):
    try:
        _, html = fetch(url)
    except Exception as e:
        log(f"index failed {url}: {e}"); return
    base = url.rsplit("/", 1)[0] + "/"
    for h in _links(html):
        u = base + h
        if u in seen:
            continue
        seen.add(u)
        if h.lower().endswith("index.htm"):
            yield from _walk(u, seen)
            continue
        try:
            s = _section(u)
        except Exception as e:
            log(f"failed {u}: {e}"); continue
        if s and s["text"]:
            yield s

def sections():
    _, idx = fetch(BASE)
    titles = []
    for t in re.findall(r'(?i)href="(TITLE[0-9A-Z.]+/INDEX\.HTM)"', idx):
        if t not in titles:
            titles.append(t)
    log(f"{len(titles)} titles")
    seen = set()
    for t in titles:
        n = 0
        for s in _walk(BASE + t, seen):
            n += 1
            yield s
        log(f"{t.split('/')[0]}: {n} sections")
